import type { Metadata, Viewport } from "next";
import { notFound } from "next/navigation";
import Script from "next/script";
import "@fontsource-variable/outfit";
import "@fontsource-variable/vazirmatn";
import "../globals.css";
import "../blog.css";
import { getDirection, isLocale, locales } from "@/lib/i18n";
import { ThemeToggle } from "@/components/theme/ThemeToggle";
import { GoghdiWidget } from "@/components/goghdi/GoghdiWidget";
import { TrafficSourceCapture } from "@/components/TrafficSourceCapture";
import { PlatformNotice } from "@/components/PlatformNotice";
import { MaintenanceGate } from "@/components/MaintenanceGate";
import { SITE_URL } from "@/lib/seo";
import { getSeoConfiguration } from "@/lib/seo-settings-server";

type LocaleLayoutProps = Readonly<{
  children: React.ReactNode;
  params: Promise<{
    locale: string;
  }>;
}>;

export function generateStaticParams() {
  return locales.map((locale) => ({ locale }));
}

export async function generateMetadata({ params }: LocaleLayoutProps): Promise<Metadata> {
  const { locale } = await params;
  const settings = await getSeoConfiguration();
  const defaults = settings.locales.find((item) => item.locale === locale) ?? settings.locales[0]!;
  return {
  metadataBase: new URL(SITE_URL),
  title: {
    default: defaults.siteName,
    template: defaults.titleTemplate
  },
  applicationName: "Top GSM",
  description: defaults.description || undefined,
  verification: { google: settings.googleVerification || undefined, other: settings.bingVerification ? { "msvalidate.01": settings.bingVerification } : undefined },
  formatDetection: {
    telephone: false
  }
  };
}

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  themeColor: "#f6f7f8",
  colorScheme: "light dark"
};

const themeScript = `
  (() => {
    try {
      const storedTheme = localStorage.getItem("topgsm-theme");
      const theme = storedTheme === "light" || storedTheme === "dark"
        ? storedTheme
        : matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
      document.documentElement.dataset.theme = theme;
      document.documentElement.style.colorScheme = theme;
      document.querySelector('meta[name="theme-color"]')?.setAttribute(
        "content",
        theme === "dark" ? "#011627" : "#f6f7f8"
      );
    } catch {
      document.documentElement.dataset.theme = "light";
    }
  })();
`;

export default async function LocaleLayout({ children, params }: LocaleLayoutProps) {
  const { locale } = await params;

  if (!isLocale(locale)) {
    notFound();
  }

  return (
    <html
      lang={locale}
      dir={getDirection(locale)}
      data-scroll-behavior="smooth"
      suppressHydrationWarning
    >
      <head>
        <Script id="topgsm-theme" strategy="beforeInteractive" dangerouslySetInnerHTML={{ __html: themeScript }} />
      </head>
      <body>
        <MaintenanceGate locale={locale} />
        <TrafficSourceCapture />
        <PlatformNotice />
        {children}
        <GoghdiWidget />
        <ThemeToggle locale={locale} />
      </body>
    </html>
  );
}
